sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float levels;
uniform float offset;

half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float3 rgb = float3(col.rgb / col.a);
    float n = max(levels, 1.0);
    float3 q = clamp((floor(rgb * n + offset) - offset) / n, 0.0, 1.0);
    return half4(half3(q) * col.a, col.a);
}
